RESET ROLE;

SET LOCAL ROLE ot_v3_jobs_owner;
CREATE OR REPLACE FUNCTION official_v3_jobs_private.context_v1(v jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE PARALLEL UNSAFE SECURITY INVOKER CALLED ON NULL INPUT SET search_path=pg_catalog,pg_temp AS $customer_body$
DECLARE s jsonb:=v->'scope'; c jsonb:=v->'conditions'; o jsonb:=s->'credentialOption'; r jsonb:=s->'residence';
  a jsonb:=v->'application'; normal jsonb; semantic jsonb; countries text[]:=ARRAY['AD','AE','AF','AG','AI','AL','AM','AO','AQ','AR','AS','AT','AU','AW','AX','AZ','BA','BB','BD','BE','BF','BG','BH','BI','BJ','BL','BM','BN','BO','BQ','BR','BS','BT','BV','BW','BY','BZ','CA','CC','CD','CF','CG','CH','CI','CK','CL','CM','CN','CO','CR','CU','CV','CW','CX','CY','CZ','DE','DJ','DK','DM','DO','DZ','EC','EE','EG','EH','ER','ES','ET','FI','FJ','FK','FM','FO','FR','GA','GB','GD','GE','GF','GG','GH','GI','GL','GM','GN','GP','GQ','GR','GS','GT','GU','GW','GY','HK','HM','HN','HR','HT','HU','ID','IE','IL','IM','IN','IO','IQ','IR','IS','IT','JE','JM','JO','JP','KE','KG','KH','KI','KM','KN','KP','KR','KW','KY','KZ','LA','LB','LC','LI','LK','LR','LS','LT','LU','LV','LY','MA','MC','MD','ME','MF','MG','MH','MK','ML','MM','MN','MO','MP','MQ','MR','MS','MT','MU','MV','MW','MX','MY','MZ','NA','NC','NE','NF','NG','NI','NL','NO','NP','NR','NU','NZ','OM','PA','PE','PF','PG','PH','PK','PL','PM','PN','PR','PS','PT','PW','PY','QA','RE','RO','RS','RU','RW','SA','SB','SC','SD','SE','SG','SH','SI','SJ','SK','SL','SM','SN','SO','SR','SS','ST','SV','SX','SY','SZ','TC','TD','TF','TG','TH','TJ','TK','TL','TM','TN','TO','TR','TT','TV','TW','TZ','UA','UG','UM','US','UY','UZ','VA','VC','VE','VG','VI','VN','VU','WF','WS','YE','YT','ZA','ZM','ZW']; missing jsonb;
BEGIN
  IF official_v3_jobs_private.exact_keys_v1(v,CASE WHEN v->'contextRevision'='3'::jsonb THEN ARRAY['contextRevision','informationTopic','informationItem','scope','route','conditions'] WHEN v?'contextRevision' THEN ARRAY['contextRevision','scope','route','conditions','application'] ELSE ARRAY['scope','route','conditions'] END) IS NOT TRUE
    OR official_v3_jobs_private.nodes_v1(v,0,16,8192)<0 OR octet_length(official_v3_jobs_private.canonical_v1(v,0))>65536
    OR official_v3_jobs_private.exact_keys_v1(s,ARRAY['destinationCountryCode','transitCountryCode','citizenship','credentialOption','residence','requirementType','validity']) IS NOT TRUE
    OR (s->>'destinationCountryCode'=ANY(countries)) IS NOT TRUE
    OR (s->'transitCountryCode'<>'null'::jsonb AND (s->>'transitCountryCode'=ANY(countries)) IS NOT TRUE)
    OR official_v3_jobs_private.exact_keys_v1(s->'citizenship',ARRAY['mode','countryCodes']) IS NOT TRUE
    OR s#>>'{citizenship,mode}' IS DISTINCT FROM 'required' OR jsonb_typeof(s#>'{citizenship,countryCodes}') IS DISTINCT FROM 'array'
    OR jsonb_array_length(s#>'{citizenship,countryCodes}')<>1 OR (s#>>'{citizenship,countryCodes,0}'=ANY(countries)) IS NOT TRUE
    OR s->'validity'<>'{"mode":"not_applicable"}'::jsonb
    OR (s->>'requirementType' IN ('visa','electronic_travel_authorization','passport','identity_document','passport_validity','blank_passport_pages','transit','health','vaccination','health_document','entry_form','insurance','onward_or_return_ticket','booking_or_travel_document','financial_means','other_entry_requirement')) IS NOT TRUE
    OR (v->>'route' IN ('direct_entry','transit','unresolved')) IS NOT TRUE
    OR (v->>'route'='direct_entry' AND s->'transitCountryCode'<>'null'::jsonb)
    OR (v->>'route'='transit' AND s->'transitCountryCode'='null'::jsonb) THEN RAISE EXCEPTION 'm04 invalid context' USING ERRCODE='P7601'; END IF;
  IF o<>'{"mode":"not_applicable"}'::jsonb THEN
    IF official_v3_jobs_private.exact_keys_v1(o,ARRAY['mode','documentType','issuingCountryCode','relatedCitizenshipCountryCode']) IS NOT TRUE
      OR o->>'mode' IS DISTINCT FROM 'option' OR (o->>'documentType' IN ('passport','national_id','unknown')) IS NOT TRUE
      OR (o->>'issuingCountryCode'=ANY(countries)) IS NOT TRUE
      OR (o->'relatedCitizenshipCountryCode'<>'null'::jsonb AND o->'relatedCitizenshipCountryCode'<>s#>'{citizenship,countryCodes,0}') THEN
      RAISE EXCEPTION 'm04 invalid credential' USING ERRCODE='P7601'; END IF;
  END IF;
  IF r<>'{"mode":"not_applicable"}'::jsonb AND (official_v3_jobs_private.exact_keys_v1(r,ARRAY['mode','countryCode']) IS NOT TRUE
    OR r->>'mode' IS DISTINCT FROM 'required' OR (r->>'countryCode'=ANY(countries)) IS NOT TRUE) THEN RAISE EXCEPTION 'm04 invalid residence' USING ERRCODE='P7601'; END IF;
  IF c->>'status'='specified' THEN
    IF official_v3_jobs_private.exact_keys_v1(c,ARRAY['status','expression']) IS NOT TRUE THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
    normal:=official_v3_jobs_private.expression_v1(c->'expression',false,1);
    IF normal<>c->'expression' THEN RAISE EXCEPTION 'm04 nonnormal context' USING ERRCODE='P7601'; END IF;
    c:=jsonb_build_object('status','specified','expression','rule-applicability-structure:v2:'||official_v3_jobs_private.canonical_v1(official_v3_jobs_private.expression_v1(normal,true,1),0));
  ELSIF c->>'status'='unresolved' THEN
    IF official_v3_jobs_private.exact_keys_v1(c,ARRAY['status','missing']) IS NOT TRUE OR jsonb_typeof(c->'missing') IS DISTINCT FROM 'array'
      OR jsonb_array_length(c->'missing') NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(c->'missing') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string'
      OR (x#>>'{}' IN ('document_class','travel_purpose','planned_stay_duration','transit','other_rule_conditions')) IS NOT TRUE) THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
    SELECT jsonb_agg(x ORDER BY x COLLATE "C") INTO missing FROM (SELECT DISTINCT value x FROM jsonb_array_elements_text(c->'missing')) q;
    IF missing<>c->'missing' THEN RAISE EXCEPTION 'm04 nonnormal conditions' USING ERRCODE='P7601'; END IF;
  ELSIF c<>'{"status":"unconditional"}'::jsonb THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
  semantic:=jsonb_build_object('scope',s,'route',v->'route','conditions',c);
  IF v->'contextRevision'='3'::jsonb THEN
    IF jsonb_typeof(v->'informationTopic') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v->'informationItem') IS DISTINCT FROM 'string'
      OR length(v->>'informationItem')>64
      OR (v->>'informationItem' ~ '^[a-z]{2,24}(?:_[a-z]{2,24}){0,7}$') IS NOT TRUE
      OR ((v->>'informationTopic'='required_vaccinations' AND s->>'requirementType'='vaccination')
      OR (v->>'informationTopic'='recommended_vaccinations' AND s->>'requirementType'='vaccination')
      OR (v->>'informationTopic'='health_measures' AND s->>'requirementType'='health')
      OR (v->>'informationTopic'='entry_forms' AND s->>'requirementType'='entry_form')
      OR (v->>'informationTopic'='form_costs' AND s->>'requirementType'='entry_form')
      OR (v->>'informationTopic'='entry_fees' AND s->>'requirementType'='visa')
      OR (v->>'informationTopic'='entry_fees' AND s->>'requirementType'='electronic_travel_authorization')
      OR (v->>'informationTopic'='entry_fees' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='fraud_warnings' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='onward_return_ticket' AND s->>'requirementType'='onward_or_return_ticket')
      OR (v->>'informationTopic'='financial_means' AND s->>'requirementType'='financial_means')
      OR (v->>'informationTopic'='minors' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='parental_consent' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='customs' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='identity_document' AND s->>'requirementType'='identity_document')
      OR (v->>'informationTopic'='dual_nationals' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='recent_changes' AND s->>'requirementType'='other_entry_requirement')) IS NOT TRUE THEN
      RAISE EXCEPTION 'm04 invalid customer information context' USING ERRCODE='P7601'; END IF;
    semantic:=semantic||jsonb_build_object('contextRevision',3,'informationTopic',v->'informationTopic','informationItem',v->'informationItem');
  ELSIF v?'contextRevision' THEN
    IF v->'contextRevision'<>'2'::jsonb OR official_v3_jobs_private.exact_keys_v1(a,ARRAY['purpose','tripStartAndEndWindow']) IS NOT TRUE
      OR a->>'purpose' IS DISTINCT FROM 'tourism' OR official_v3_jobs_private.exact_keys_v1(a->'tripStartAndEndWindow',ARRAY['from','through']) IS NOT TRUE
      OR official_v3_jobs_private.civil_date_v1(a#>>'{tripStartAndEndWindow,from}') IS NOT TRUE
      OR official_v3_jobs_private.civil_date_v1(a#>>'{tripStartAndEndWindow,through}') IS NOT TRUE
      OR a#>>'{tripStartAndEndWindow,from}'>a#>>'{tripStartAndEndWindow,through}' THEN RAISE EXCEPTION 'm04 invalid application' USING ERRCODE='P7601'; END IF;
    semantic:=semantic||jsonb_build_object('contextRevision',2,'application',a);
  END IF;
  RETURN semantic;
END $customer_body$;
RESET ROLE;

SET LOCAL ROLE ot_v3_jobs_owner;
CREATE OR REPLACE FUNCTION official_v3_jobs_private.subject_v1(kind text,v jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE PARALLEL UNSAFE SECURITY INVOKER CALLED ON NULL INPUT SET search_path=pg_catalog,pg_temp AS $customer_body$
DECLARE m jsonb:=v->'method'; context jsonb; s jsonb; o jsonb; r jsonb; preimage jsonb; ck text; jk text; sk text; rk text; legacy text; research jsonb; pair_text text; countries text[]:=ARRAY['AD','AE','AF','AG','AI','AL','AM','AO','AQ','AR','AS','AT','AU','AW','AX','AZ','BA','BB','BD','BE','BF','BG','BH','BI','BJ','BL','BM','BN','BO','BQ','BR','BS','BT','BV','BW','BY','BZ','CA','CC','CD','CF','CG','CH','CI','CK','CL','CM','CN','CO','CR','CU','CV','CW','CX','CY','CZ','DE','DJ','DK','DM','DO','DZ','EC','EE','EG','EH','ER','ES','ET','FI','FJ','FK','FM','FO','FR','GA','GB','GD','GE','GF','GG','GH','GI','GL','GM','GN','GP','GQ','GR','GS','GT','GU','GW','GY','HK','HM','HN','HR','HT','HU','ID','IE','IL','IM','IN','IO','IQ','IR','IS','IT','JE','JM','JO','JP','KE','KG','KH','KI','KM','KN','KP','KR','KW','KY','KZ','LA','LB','LC','LI','LK','LR','LS','LT','LU','LV','LY','MA','MC','MD','ME','MF','MG','MH','MK','ML','MM','MN','MO','MP','MQ','MR','MS','MT','MU','MV','MW','MX','MY','MZ','NA','NC','NE','NF','NG','NI','NL','NO','NP','NR','NU','NZ','OM','PA','PE','PF','PG','PH','PK','PL','PM','PN','PR','PS','PT','PW','PY','QA','RE','RO','RS','RU','RW','SA','SB','SC','SD','SE','SG','SH','SI','SJ','SK','SL','SM','SN','SO','SR','SS','ST','SV','SX','SY','SZ','TC','TD','TF','TG','TH','TJ','TK','TL','TM','TN','TO','TR','TT','TV','TW','TZ','UA','UG','UM','US','UY','UZ','VA','VC','VE','VG','VI','VN','VU','WF','WS','YE','YT','ZA','ZM','ZW'];
BEGIN
  IF official_v3_jobs_private.exact_keys_v1(m,ARRAY['methodId','revision']) IS NOT TRUE OR jsonb_typeof(m->'methodId') IS DISTINCT FROM 'string' OR (m->>'methodId' ~ '^[a-z][a-z0-9_-]{1,63}$') IS NOT TRUE
    OR jsonb_typeof(m->'revision') IS DISTINCT FROM 'number' OR m->>'revision' !~ '^[1-9][0-9]{0,9}$' OR (m->>'revision')::numeric>2147483647 THEN RAISE EXCEPTION 'm04 invalid method' USING ERRCODE='P7601'; END IF;
  IF kind='combination_discovery' THEN
    IF official_v3_jobs_private.exact_keys_v1(v,ARRAY['destinationCountryCode','citizenshipCountryCode','method']) IS NOT TRUE
      OR (v->>'destinationCountryCode'=ANY(countries)) IS NOT TRUE OR (v->>'citizenshipCountryCode'=ANY(countries)) IS NOT TRUE THEN RAISE EXCEPTION 'm04 invalid pair' USING ERRCODE='P7601'; END IF;
    pair_text:=official_v3_jobs_private.canonical_v1(v,0);
    jk:='combination-discovery-job:v3:'||encode(sha256(convert_to(pair_text,'UTF8')),'hex');
    RETURN jsonb_build_object('kind',kind,'jobKey',jk,'subjectText',(CASE WHEN jsonb_typeof(v->'citizenshipCountryCode')='string' AND jsonb_typeof(v->'destinationCountryCode')='string'
      THEN overlay(pair_text placing ',"kind":'||official_v3_jobs_private.canonical_v1(to_jsonb(kind),1) from strpos(pair_text COLLATE "C",',"method":') for 0)
      ELSE official_v3_jobs_private.canonical_v1(v||jsonb_build_object('kind',kind),0) END),'contextKey',NULL);
  END IF;
  IF kind IS DISTINCT FROM 'rule_research' OR official_v3_jobs_private.exact_keys_v1(v,ARRAY['context','method','factKind','researchReason']) IS NOT TRUE
    OR (v->>'factKind' IN ('passport_validity','blank_passport_pages','requirement_effect','visa_options','stay_limit','transit_conditions','official_actions','temporal_rule','entry_information')) IS NOT TRUE THEN RAISE EXCEPTION 'm04 invalid subject' USING ERRCODE='P7601'; END IF;
  IF COALESCE(v#>'{context,contextRevision}'='3'::jsonb,false) IS DISTINCT FROM (v->>'factKind'='entry_information') THEN
    RAISE EXCEPTION 'm04 customer information fact/context mismatch' USING ERRCODE='P7601'; END IF;
  r:=v->'researchReason';
  IF r<>'{"status":"missing"}'::jsonb AND (official_v3_jobs_private.exact_keys_v1(r,ARRAY['status','reason']) IS NOT TRUE
    OR r->>'status' IS DISTINCT FROM 'recheck_needed' OR (r->>'reason' IN ('valid_from_in_future','valid_until_elapsed','max_age_exceeded')) IS NOT TRUE) THEN RAISE EXCEPTION 'm04 invalid reason' USING ERRCODE='P7601'; END IF;
  context:=official_v3_jobs_private.context_v1(v->'context'); s:=context->'scope'; o:=s->'credentialOption';
  ck:='official-truth-context:v3:'||encode(sha256(convert_to(official_v3_jobs_private.canonical_v1(context,0),'UTF8')),'hex');
  -- Legacy insertion order is deliberately distinct from canonical_v1 object order.
  legacy:='{"v":1,"destinationCountryCode":'||(s->'destinationCountryCode')::text||',"transitCountryCode":'||(s->'transitCountryCode')::text
    ||',"citizenshipMode":"required","citizenshipCountryCodes":'||official_v3_jobs_private.canonical_v1(s#>'{citizenship,countryCodes}',0)
    ||',"credentialOptionMode":'||(o->'mode')::text||',"documentType":'||COALESCE((o->'documentType')::text,'null')
    ||',"issuingCountryCode":'||COALESCE((o->'issuingCountryCode')::text,'null')||',"relatedCitizenshipCountryCode":'||COALESCE((o->'relatedCitizenshipCountryCode')::text,'null')
    ||',"relation":'||to_jsonb(CASE WHEN o->>'mode'='not_applicable' THEN 'not_applicable' WHEN o->'relatedCitizenshipCountryCode'='null'::jsonb THEN 'unlinked' ELSE 'explicit' END)::text
    ||',"residenceMode":'||(s#>'{residence,mode}')::text||',"residenceCountryCode":'||COALESCE((s#>'{residence,countryCode}')::text,'null')
    ||',"requirementType":'||(s->'requirementType')::text||',"validityMode":"not_applicable","travelDate":null}';
  sk:='rule-scope:v1:'||encode(sha256(convert_to(legacy,'UTF8')),'hex');
  rk:='research-request:v1:'||encode(sha256(convert_to('{"v":1,"ruleScopeKey":'||to_jsonb(sk)::text||',"factKind":'||(v->'factKind')::text
    ||',"status":'||(r->'status')::text||',"recheckReason":'||COALESCE((r->'reason')::text,'null')||'}','UTF8')),'hex');
  research:=jsonb_build_object('key',rk,'ruleScopeKey',sk,'factKind',v->'factKind','researchReason',r);
  jk:='research-job:v3:'||encode(sha256(convert_to(official_v3_jobs_private.canonical_v1(jsonb_build_object('contextKey',ck,'method',m,'factKind',v->'factKind'),0),'UTF8')),'hex');
  preimage:=jsonb_build_object('kind',kind,'context',context,'method',m,'factKind',v->'factKind');
  RETURN jsonb_build_object('kind',kind,'jobKey',jk,'subjectText',official_v3_jobs_private.canonical_v1(preimage,0),'contextKey',ck,'research',research);
END $customer_body$;
RESET ROLE;

SET LOCAL ROLE ot_v3_result_owner;
CREATE OR REPLACE FUNCTION official_v3_result_private.context_v1(v jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE PARALLEL UNSAFE SECURITY INVOKER CALLED ON NULL INPUT SET search_path=pg_catalog,pg_temp AS $customer_body$
DECLARE s jsonb:=v->'scope'; c jsonb:=v->'conditions'; o jsonb:=s->'credentialOption'; r jsonb:=s->'residence';
  a jsonb:=v->'application'; normal jsonb; semantic jsonb; countries text[]:=ARRAY['AD','AE','AF','AG','AI','AL','AM','AO','AQ','AR','AS','AT','AU','AW','AX','AZ','BA','BB','BD','BE','BF','BG','BH','BI','BJ','BL','BM','BN','BO','BQ','BR','BS','BT','BV','BW','BY','BZ','CA','CC','CD','CF','CG','CH','CI','CK','CL','CM','CN','CO','CR','CU','CV','CW','CX','CY','CZ','DE','DJ','DK','DM','DO','DZ','EC','EE','EG','EH','ER','ES','ET','FI','FJ','FK','FM','FO','FR','GA','GB','GD','GE','GF','GG','GH','GI','GL','GM','GN','GP','GQ','GR','GS','GT','GU','GW','GY','HK','HM','HN','HR','HT','HU','ID','IE','IL','IM','IN','IO','IQ','IR','IS','IT','JE','JM','JO','JP','KE','KG','KH','KI','KM','KN','KP','KR','KW','KY','KZ','LA','LB','LC','LI','LK','LR','LS','LT','LU','LV','LY','MA','MC','MD','ME','MF','MG','MH','MK','ML','MM','MN','MO','MP','MQ','MR','MS','MT','MU','MV','MW','MX','MY','MZ','NA','NC','NE','NF','NG','NI','NL','NO','NP','NR','NU','NZ','OM','PA','PE','PF','PG','PH','PK','PL','PM','PN','PR','PS','PT','PW','PY','QA','RE','RO','RS','RU','RW','SA','SB','SC','SD','SE','SG','SH','SI','SJ','SK','SL','SM','SN','SO','SR','SS','ST','SV','SX','SY','SZ','TC','TD','TF','TG','TH','TJ','TK','TL','TM','TN','TO','TR','TT','TV','TW','TZ','UA','UG','UM','US','UY','UZ','VA','VC','VE','VG','VI','VN','VU','WF','WS','YE','YT','ZA','ZM','ZW']; missing jsonb;
BEGIN
  IF official_v3_result_private.exact_keys_v1(v,CASE WHEN v->'contextRevision'='3'::jsonb THEN ARRAY['contextRevision','informationTopic','informationItem','scope','route','conditions'] WHEN v?'contextRevision' THEN ARRAY['contextRevision','scope','route','conditions','application'] ELSE ARRAY['scope','route','conditions'] END) IS NOT TRUE
    OR official_v3_result_private.nodes_v1(v,0,16,8192)<0 OR octet_length(official_v3_result_private.canonical_v1(v,0))>65536
    OR official_v3_result_private.exact_keys_v1(s,ARRAY['destinationCountryCode','transitCountryCode','citizenship','credentialOption','residence','requirementType','validity']) IS NOT TRUE
    OR (s->>'destinationCountryCode'=ANY(countries)) IS NOT TRUE
    OR (s->'transitCountryCode'<>'null'::jsonb AND (s->>'transitCountryCode'=ANY(countries)) IS NOT TRUE)
    OR official_v3_result_private.exact_keys_v1(s->'citizenship',ARRAY['mode','countryCodes']) IS NOT TRUE
    OR s#>>'{citizenship,mode}' IS DISTINCT FROM 'required' OR jsonb_typeof(s#>'{citizenship,countryCodes}') IS DISTINCT FROM 'array'
    OR jsonb_array_length(s#>'{citizenship,countryCodes}')<>1 OR (s#>>'{citizenship,countryCodes,0}'=ANY(countries)) IS NOT TRUE
    OR s->'validity'<>'{"mode":"not_applicable"}'::jsonb
    OR (s->>'requirementType' IN ('visa','electronic_travel_authorization','passport','identity_document','passport_validity','blank_passport_pages','transit','health','vaccination','health_document','entry_form','insurance','onward_or_return_ticket','booking_or_travel_document','financial_means','other_entry_requirement')) IS NOT TRUE
    OR (v->>'route' IN ('direct_entry','transit','unresolved')) IS NOT TRUE
    OR (v->>'route'='direct_entry' AND s->'transitCountryCode'<>'null'::jsonb)
    OR (v->>'route'='transit' AND s->'transitCountryCode'='null'::jsonb) THEN RAISE EXCEPTION 'm04 invalid context' USING ERRCODE='P7601'; END IF;
  IF o<>'{"mode":"not_applicable"}'::jsonb THEN
    IF official_v3_result_private.exact_keys_v1(o,ARRAY['mode','documentType','issuingCountryCode','relatedCitizenshipCountryCode']) IS NOT TRUE
      OR o->>'mode' IS DISTINCT FROM 'option' OR (o->>'documentType' IN ('passport','national_id','unknown')) IS NOT TRUE
      OR (o->>'issuingCountryCode'=ANY(countries)) IS NOT TRUE
      OR (o->'relatedCitizenshipCountryCode'<>'null'::jsonb AND o->'relatedCitizenshipCountryCode'<>s#>'{citizenship,countryCodes,0}') THEN
      RAISE EXCEPTION 'm04 invalid credential' USING ERRCODE='P7601'; END IF;
  END IF;
  IF r<>'{"mode":"not_applicable"}'::jsonb AND (official_v3_result_private.exact_keys_v1(r,ARRAY['mode','countryCode']) IS NOT TRUE
    OR r->>'mode' IS DISTINCT FROM 'required' OR (r->>'countryCode'=ANY(countries)) IS NOT TRUE) THEN RAISE EXCEPTION 'm04 invalid residence' USING ERRCODE='P7601'; END IF;
  IF c->>'status'='specified' THEN
    IF official_v3_result_private.exact_keys_v1(c,ARRAY['status','expression']) IS NOT TRUE THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
    normal:=official_v3_result_private.expression_v1(c->'expression',false,1);
    IF normal<>c->'expression' THEN RAISE EXCEPTION 'm04 nonnormal context' USING ERRCODE='P7601'; END IF;
    c:=jsonb_build_object('status','specified','expression','rule-applicability-structure:v2:'||official_v3_result_private.canonical_v1(official_v3_result_private.expression_v1(normal,true,1),0));
  ELSIF c->>'status'='unresolved' THEN
    IF official_v3_result_private.exact_keys_v1(c,ARRAY['status','missing']) IS NOT TRUE OR jsonb_typeof(c->'missing') IS DISTINCT FROM 'array'
      OR jsonb_array_length(c->'missing') NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(c->'missing') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string'
      OR (x#>>'{}' IN ('document_class','travel_purpose','planned_stay_duration','transit','other_rule_conditions')) IS NOT TRUE) THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
    SELECT jsonb_agg(x ORDER BY x COLLATE "C") INTO missing FROM (SELECT DISTINCT value x FROM jsonb_array_elements_text(c->'missing')) q;
    IF missing<>c->'missing' THEN RAISE EXCEPTION 'm04 nonnormal conditions' USING ERRCODE='P7601'; END IF;
  ELSIF c<>'{"status":"unconditional"}'::jsonb THEN RAISE EXCEPTION 'm04 invalid conditions' USING ERRCODE='P7601'; END IF;
  semantic:=jsonb_build_object('scope',s,'route',v->'route','conditions',c);
  IF v->'contextRevision'='3'::jsonb THEN
    IF jsonb_typeof(v->'informationTopic') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v->'informationItem') IS DISTINCT FROM 'string'
      OR length(v->>'informationItem')>64
      OR (v->>'informationItem' ~ '^[a-z]{2,24}(?:_[a-z]{2,24}){0,7}$') IS NOT TRUE
      OR ((v->>'informationTopic'='required_vaccinations' AND s->>'requirementType'='vaccination')
      OR (v->>'informationTopic'='recommended_vaccinations' AND s->>'requirementType'='vaccination')
      OR (v->>'informationTopic'='health_measures' AND s->>'requirementType'='health')
      OR (v->>'informationTopic'='entry_forms' AND s->>'requirementType'='entry_form')
      OR (v->>'informationTopic'='form_costs' AND s->>'requirementType'='entry_form')
      OR (v->>'informationTopic'='entry_fees' AND s->>'requirementType'='visa')
      OR (v->>'informationTopic'='entry_fees' AND s->>'requirementType'='electronic_travel_authorization')
      OR (v->>'informationTopic'='entry_fees' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='fraud_warnings' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='onward_return_ticket' AND s->>'requirementType'='onward_or_return_ticket')
      OR (v->>'informationTopic'='financial_means' AND s->>'requirementType'='financial_means')
      OR (v->>'informationTopic'='minors' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='parental_consent' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='customs' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='identity_document' AND s->>'requirementType'='identity_document')
      OR (v->>'informationTopic'='dual_nationals' AND s->>'requirementType'='other_entry_requirement')
      OR (v->>'informationTopic'='recent_changes' AND s->>'requirementType'='other_entry_requirement')) IS NOT TRUE THEN
      RAISE EXCEPTION 'm04 invalid customer information context' USING ERRCODE='P7601'; END IF;
    semantic:=semantic||jsonb_build_object('contextRevision',3,'informationTopic',v->'informationTopic','informationItem',v->'informationItem');
  ELSIF v?'contextRevision' THEN
    IF v->'contextRevision'<>'2'::jsonb OR official_v3_result_private.exact_keys_v1(a,ARRAY['purpose','tripStartAndEndWindow']) IS NOT TRUE
      OR a->>'purpose' IS DISTINCT FROM 'tourism' OR official_v3_result_private.exact_keys_v1(a->'tripStartAndEndWindow',ARRAY['from','through']) IS NOT TRUE
      OR official_v3_result_private.civil_date_v1(a#>>'{tripStartAndEndWindow,from}') IS NOT TRUE
      OR official_v3_result_private.civil_date_v1(a#>>'{tripStartAndEndWindow,through}') IS NOT TRUE
      OR a#>>'{tripStartAndEndWindow,from}'>a#>>'{tripStartAndEndWindow,through}' THEN RAISE EXCEPTION 'm04 invalid application' USING ERRCODE='P7601'; END IF;
    semantic:=semantic||jsonb_build_object('contextRevision',2,'application',a);
  END IF;
  RETURN semantic;
END $customer_body$;
RESET ROLE;

SET LOCAL ROLE ot_v3_result_owner;
CREATE OR REPLACE FUNCTION official_v3_result_private.subject_v1(kind text,v jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE PARALLEL UNSAFE SECURITY INVOKER CALLED ON NULL INPUT SET search_path=pg_catalog,pg_temp AS $customer_body$
DECLARE m jsonb:=v->'method'; context jsonb; s jsonb; o jsonb; r jsonb; preimage jsonb; ck text; jk text; sk text; rk text; legacy text; research jsonb; pair_text text; countries text[]:=ARRAY['AD','AE','AF','AG','AI','AL','AM','AO','AQ','AR','AS','AT','AU','AW','AX','AZ','BA','BB','BD','BE','BF','BG','BH','BI','BJ','BL','BM','BN','BO','BQ','BR','BS','BT','BV','BW','BY','BZ','CA','CC','CD','CF','CG','CH','CI','CK','CL','CM','CN','CO','CR','CU','CV','CW','CX','CY','CZ','DE','DJ','DK','DM','DO','DZ','EC','EE','EG','EH','ER','ES','ET','FI','FJ','FK','FM','FO','FR','GA','GB','GD','GE','GF','GG','GH','GI','GL','GM','GN','GP','GQ','GR','GS','GT','GU','GW','GY','HK','HM','HN','HR','HT','HU','ID','IE','IL','IM','IN','IO','IQ','IR','IS','IT','JE','JM','JO','JP','KE','KG','KH','KI','KM','KN','KP','KR','KW','KY','KZ','LA','LB','LC','LI','LK','LR','LS','LT','LU','LV','LY','MA','MC','MD','ME','MF','MG','MH','MK','ML','MM','MN','MO','MP','MQ','MR','MS','MT','MU','MV','MW','MX','MY','MZ','NA','NC','NE','NF','NG','NI','NL','NO','NP','NR','NU','NZ','OM','PA','PE','PF','PG','PH','PK','PL','PM','PN','PR','PS','PT','PW','PY','QA','RE','RO','RS','RU','RW','SA','SB','SC','SD','SE','SG','SH','SI','SJ','SK','SL','SM','SN','SO','SR','SS','ST','SV','SX','SY','SZ','TC','TD','TF','TG','TH','TJ','TK','TL','TM','TN','TO','TR','TT','TV','TW','TZ','UA','UG','UM','US','UY','UZ','VA','VC','VE','VG','VI','VN','VU','WF','WS','YE','YT','ZA','ZM','ZW'];
BEGIN
  IF official_v3_result_private.exact_keys_v1(m,ARRAY['methodId','revision']) IS NOT TRUE OR jsonb_typeof(m->'methodId') IS DISTINCT FROM 'string' OR (m->>'methodId' ~ '^[a-z][a-z0-9_-]{1,63}$') IS NOT TRUE
    OR jsonb_typeof(m->'revision') IS DISTINCT FROM 'number' OR m->>'revision' !~ '^[1-9][0-9]{0,9}$' OR (m->>'revision')::numeric>2147483647 THEN RAISE EXCEPTION 'm04 invalid method' USING ERRCODE='P7601'; END IF;
  IF kind='combination_discovery' THEN
    IF official_v3_result_private.exact_keys_v1(v,ARRAY['destinationCountryCode','citizenshipCountryCode','method']) IS NOT TRUE
      OR (v->>'destinationCountryCode'=ANY(countries)) IS NOT TRUE OR (v->>'citizenshipCountryCode'=ANY(countries)) IS NOT TRUE THEN RAISE EXCEPTION 'm04 invalid pair' USING ERRCODE='P7601'; END IF;
    pair_text:=official_v3_result_private.canonical_v1(v,0);
    jk:='combination-discovery-job:v3:'||encode(sha256(convert_to(pair_text,'UTF8')),'hex');
    RETURN jsonb_build_object('kind',kind,'jobKey',jk,'subjectText',(CASE WHEN jsonb_typeof(v->'citizenshipCountryCode')='string' AND jsonb_typeof(v->'destinationCountryCode')='string'
      THEN overlay(pair_text placing ',"kind":'||official_v3_result_private.canonical_v1(to_jsonb(kind),1) from strpos(pair_text COLLATE "C",',"method":') for 0)
      ELSE official_v3_result_private.canonical_v1(v||jsonb_build_object('kind',kind),0) END),'contextKey',NULL);
  END IF;
  IF kind IS DISTINCT FROM 'rule_research' OR official_v3_result_private.exact_keys_v1(v,ARRAY['context','method','factKind','researchReason']) IS NOT TRUE
    OR (v->>'factKind' IN ('passport_validity','blank_passport_pages','requirement_effect','visa_options','stay_limit','transit_conditions','official_actions','temporal_rule','entry_information')) IS NOT TRUE THEN RAISE EXCEPTION 'm04 invalid subject' USING ERRCODE='P7601'; END IF;
  IF COALESCE(v#>'{context,contextRevision}'='3'::jsonb,false) IS DISTINCT FROM (v->>'factKind'='entry_information') THEN
    RAISE EXCEPTION 'm04 customer information fact/context mismatch' USING ERRCODE='P7601'; END IF;
  r:=v->'researchReason';
  IF r<>'{"status":"missing"}'::jsonb AND (official_v3_result_private.exact_keys_v1(r,ARRAY['status','reason']) IS NOT TRUE
    OR r->>'status' IS DISTINCT FROM 'recheck_needed' OR (r->>'reason' IN ('valid_from_in_future','valid_until_elapsed','max_age_exceeded')) IS NOT TRUE) THEN RAISE EXCEPTION 'm04 invalid reason' USING ERRCODE='P7601'; END IF;
  context:=official_v3_result_private.context_v1(v->'context'); s:=context->'scope'; o:=s->'credentialOption';
  ck:='official-truth-context:v3:'||encode(sha256(convert_to(official_v3_result_private.canonical_v1(context,0),'UTF8')),'hex');
  -- Legacy insertion order is deliberately distinct from canonical_v1 object order.
  legacy:='{"v":1,"destinationCountryCode":'||(s->'destinationCountryCode')::text||',"transitCountryCode":'||(s->'transitCountryCode')::text
    ||',"citizenshipMode":"required","citizenshipCountryCodes":'||official_v3_result_private.canonical_v1(s#>'{citizenship,countryCodes}',0)
    ||',"credentialOptionMode":'||(o->'mode')::text||',"documentType":'||COALESCE((o->'documentType')::text,'null')
    ||',"issuingCountryCode":'||COALESCE((o->'issuingCountryCode')::text,'null')||',"relatedCitizenshipCountryCode":'||COALESCE((o->'relatedCitizenshipCountryCode')::text,'null')
    ||',"relation":'||to_jsonb(CASE WHEN o->>'mode'='not_applicable' THEN 'not_applicable' WHEN o->'relatedCitizenshipCountryCode'='null'::jsonb THEN 'unlinked' ELSE 'explicit' END)::text
    ||',"residenceMode":'||(s#>'{residence,mode}')::text||',"residenceCountryCode":'||COALESCE((s#>'{residence,countryCode}')::text,'null')
    ||',"requirementType":'||(s->'requirementType')::text||',"validityMode":"not_applicable","travelDate":null}';
  sk:='rule-scope:v1:'||encode(sha256(convert_to(legacy,'UTF8')),'hex');
  rk:='research-request:v1:'||encode(sha256(convert_to('{"v":1,"ruleScopeKey":'||to_jsonb(sk)::text||',"factKind":'||(v->'factKind')::text
    ||',"status":'||(r->'status')::text||',"recheckReason":'||COALESCE((r->'reason')::text,'null')||'}','UTF8')),'hex');
  research:=jsonb_build_object('key',rk,'ruleScopeKey',sk,'factKind',v->'factKind','researchReason',r);
  jk:='research-job:v3:'||encode(sha256(convert_to(official_v3_result_private.canonical_v1(jsonb_build_object('contextKey',ck,'method',m,'factKind',v->'factKind'),0),'UTF8')),'hex');
  preimage:=jsonb_build_object('kind',kind,'context',context,'method',m,'factKind',v->'factKind');
  RETURN jsonb_build_object('kind',kind,'jobKey',jk,'subjectText',official_v3_result_private.canonical_v1(preimage,0),'contextKey',ck,'research',research);
END $customer_body$;
RESET ROLE;

SET LOCAL ROLE ot_v3_jobs_owner;
CREATE OR REPLACE FUNCTION official_v3_jobs_private.assert_history_v1(k text) RETURNS void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER CALLED ON NULL INPUT SET search_path=pg_catalog,pg_temp  AS $customer_body$
DECLARE s official_v3_jobs_private.subjects_v1%ROWTYPE; x record; c jsonb; e jsonb; unresolved text[]; ops integer; starts integer; credit jsonb; envelope_canonical text COLLATE "default";
  validated_jobs jsonb:='{}'::jsonb; validated_job_count integer:=0; validated_job_bytes integer:=0; job_text text COLLATE "C"; job_bytes integer;
  memo_subject_kind text COLLATE "C"; memo_subject_text text COLLATE "C"; memo_subject_result jsonb; command_identity jsonb; quota jsonb;
  canonical_memo_key_one text COLLATE "C"; canonical_memo_key_two text COLLATE "C";
  canonical_memo_value_one text; canonical_memo_value_two text;
  canonical_memo_bytes_one integer:=0; canonical_memo_bytes_two integer:=0;
  subtree_memo jsonb:='{}'; subtree_memo_count integer:=0; subtree_memo_bytes integer:=0;
  attempt_canonical text COLLATE "default";
  nodes_memo jsonb:='{}'; nodes_memo_count integer:=0; nodes_memo_bytes integer:=0; audit_canonical text COLLATE "default"; claim_canonical text COLLATE "default";
BEGIN
  SELECT * INTO s FROM official_v3_jobs_private.subjects_v1 WHERE job_key=k;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT count(*) INTO ops FROM official_v3_jobs_private.queue_operations_v1 WHERE job_key=k;
  SELECT count(*),array_agg(t.attempt_key ORDER BY t.attempt_key) FILTER(WHERE d.attempt_key IS NULL AND NOT official_v3_guard_private.attempt_retired_v1(t.attempt_key)) INTO starts,unresolved
    FROM official_v3_jobs_private.execution_starts_v1 t LEFT JOIN official_v3_jobs_private.execution_dispositions_v1 d USING(attempt_key) WHERE t.job_key=k;
  quota:=official_v3_jobs_private.rolling_usage_v2(k);
  IF ops<>s.operation_count OR starts<>s.start_count
    OR (quota->>'operations')::integer+(quota->>'credit')::integer>256 OR (quota->>'starts')::integer>64 OR cardinality(unresolved)>1
    OR s.open_attempt IS DISTINCT FROM unresolved[1] THEN RAISE EXCEPTION 'm04 history invariant' USING ERRCODE='P7603'; END IF;
  DECLARE v jsonb:=s.current_job;
  job_subject_input jsonb; job_subject_text text COLLATE "C"; job_subject_bytes integer;
  job_canonical_text text COLLATE "default";
  job_nodes integer;
  common text[] COLLATE "default":=ARRAY['schema','kind','jobId','operationId','revision','predecessorRevision','state','createdAt','updatedAt','attempt','attemptLimit','lease','nextAttemptAt','lastFailure'];
  i jsonb; result_ref jsonb; l jsonb:=v->'lease'; state text COLLATE "default":=v->>'state'; created timestamptz; updated timestamptz;
  attempt integer; lim integer; revision integer;
BEGIN
DECLARE hn_value jsonb:=v; hn_count integer:=1; hn_child record;
  hn_child_count bigint; hn_child_nodes integer; hn_key text COLLATE "C"; hn_bytes bigint;
BEGIN
  IF hn_value IS NULL THEN hn_count:=-1;
  ELSIF jsonb_typeof(hn_value)<>'object' THEN
    hn_count:=official_v3_jobs_private.nodes_v1(hn_value,0,16,8192);
  ELSE
    SELECT count(*) INTO hn_child_count FROM jsonb_object_keys(hn_value);
    IF hn_child_count>(8192-1)/2 THEN hn_count:=-1;
    ELSE
      hn_count:=1+2*hn_child_count;
      FOR hn_child IN SELECT j.key,j.value FROM jsonb_each(hn_value) j
        WHERE jsonb_typeof(j.value) IN ('object','array') LOOP
        IF hn_child.key IN ('context','research','method','identity') THEN
          -- The full key also binds every original recursive parameter.
          hn_key:='1:16:8192:'||hn_child.value::text;
          IF nodes_memo ? hn_key THEN hn_child_nodes:=(nodes_memo->>hn_key)::integer;
          ELSE
            hn_child_nodes:=official_v3_jobs_private.nodes_v1(hn_child.value,1,16,8192);
            hn_bytes:=octet_length(hn_key)::bigint+octet_length(hn_child_nodes::text)::bigint;
            IF hn_child_nodes>0 AND hn_bytes<=16384 THEN
              IF nodes_memo_count>=8 OR hn_bytes>16384-nodes_memo_bytes THEN
                nodes_memo:='{}'; nodes_memo_count:=0; nodes_memo_bytes:=0;
              END IF;
              nodes_memo:=nodes_memo||jsonb_build_object(hn_key,hn_child_nodes);
              nodes_memo_count:=nodes_memo_count+1; nodes_memo_bytes:=nodes_memo_bytes+hn_bytes::integer;
            END IF;
          END IF;
        ELSE
          hn_child_nodes:=official_v3_jobs_private.nodes_v1(hn_child.value,1,16,8192);
        END IF;
        IF hn_child_nodes<0 THEN hn_count:=-1; EXIT; END IF;
        hn_count:=hn_count+hn_child_nodes-1;
        IF hn_count>8192 THEN hn_count:=-1; EXIT; END IF;
      END LOOP;
    END IF;
  END IF;
  job_nodes:=hn_count;
END;
  IF job_nodes<0 THEN RAISE EXCEPTION 'm04 invalid job' USING ERRCODE='P7601'; END IF;
DECLARE hc0_value jsonb:=v; hc0_depth integer:=0;
  hc0_keys text[] COLLATE "default"; hc0_values jsonb[]; hc0_parts text[] COLLATE "default";
  hc0_pending integer[]; hc0_at integer; hc0_member text COLLATE "default"; hc0_child jsonb;
  hc0_text text COLLATE "default"; hc0_key text COLLATE "C"; hc0_bytes bigint; hc0_fast text COLLATE "default";
BEGIN
  IF hc0_value IS NULL OR hc0_depth IS NULL OR hc0_depth<0 OR hc0_depth>24 THEN
    RAISE EXCEPTION 'm04 invalid metadata' USING ERRCODE='P7601'; END IF;
  IF jsonb_typeof(hc0_value)<>'object' THEN
    CASE jsonb_typeof(hc0_value)
      WHEN 'string' THEN
        IF (hc0_value#>>'{}') ~ '[^ -~]' THEN RAISE EXCEPTION 'm04 invalid metadata' USING ERRCODE='P7601';END IF;
        job_canonical_text:=hc0_value::text;
      WHEN 'number' THEN
        IF hc0_value::numeric<>trunc(hc0_value::numeric) OR hc0_value::numeric NOT BETWEEN -9007199254740991 AND 9007199254740991 THEN
          RAISE EXCEPTION 'm04 invalid metadata' USING ERRCODE='P7601';END IF;
        job_canonical_text:=trunc(hc0_value::numeric)::text;
      WHEN 'boolean' THEN job_canonical_text:=hc0_value::text;
      WHEN 'null' THEN job_canonical_text:='null';
      ELSE job_canonical_text:=official_v3_jobs_private.canonical_v1(hc0_value,hc0_depth);
    END CASE;
  ELSE
    DECLARE hcf_value jsonb:=(hc0_value); hcf_depth integer:=(hc0_depth);
  hcf_parts text[] COLLATE "default"; hcf_lease_parts text[] COLLATE "default";
  hcf_lease jsonb; hcf_lease_text text COLLATE "default";
BEGIN
  hc0_fast:=NULL;
  -- All supported shapes have children. The unchanged serializer accepts the
  -- object at depth24 only when it is empty, which is deliberately a miss here.
  IF hcf_value IS NOT NULL AND hcf_depth IS NOT NULL AND hcf_depth BETWEEN 0 AND 23
    AND jsonb_typeof(hcf_value)='object' THEN
    IF hcf_value ? 'schema' THEN
IF hcf_value->'kind'='"research_job_record"'::jsonb
      AND (hcf_value ?& ARRAY['attempt','attemptLimit','context','contextKey','createdAt','jobId','jobKey','kind','lastFailure','lease','method','nextAttemptAt','operationId','predecessorRevision','research','resultDecisionRef','revision','schema','state','updatedAt']::text[] AND (hcf_value-ARRAY['attempt','attemptLimit','context','contextKey','createdAt','jobId','jobKey','kind','lastFailure','lease','method','nextAttemptAt','operationId','predecessorRevision','research','resultDecisionRef','revision','schema','state','updatedAt']::text[])='{}'::jsonb) THEN hcf_lease:=hcf_value->'lease';
    hcf_lease_text:=(CASE jsonb_typeof(hcf_lease)
      WHEN 'string' THEN CASE WHEN (hcf_lease#>>'{}') ~ '[^ -~]' THEN NULL ELSE hcf_lease::text END
      WHEN 'number' THEN CASE WHEN hcf_lease::numeric=trunc(hcf_lease::numeric)
        AND hcf_lease::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc(hcf_lease::numeric)::text END
      WHEN 'boolean' THEN hcf_lease::text WHEN 'null' THEN 'null' ELSE NULL END);
    IF hcf_lease_text IS NULL AND hcf_depth+2<=24 AND jsonb_typeof(hcf_lease)='object' THEN
      IF (hcf_lease ?& ARRAY['acquiredAt','expiresAt','generation','leaseId']::text[] AND (hcf_lease-ARRAY['acquiredAt','expiresAt','generation','leaseId']::text[])='{}'::jsonb) THEN
        hcf_lease_parts:=ARRAY[
    '"acquiredAt":'||(CASE jsonb_typeof((hcf_lease->'acquiredAt'))
      WHEN 'string' THEN CASE WHEN ((hcf_lease->'acquiredAt')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_lease->'acquiredAt')::text END
      WHEN 'number' THEN CASE WHEN (hcf_lease->'acquiredAt')::numeric=trunc((hcf_lease->'acquiredAt')::numeric)
        AND (hcf_lease->'acquiredAt')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_lease->'acquiredAt')::numeric)::text END
      WHEN 'boolean' THEN (hcf_lease->'acquiredAt')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"expiresAt":'||(CASE jsonb_typeof((hcf_lease->'expiresAt'))
      WHEN 'string' THEN CASE WHEN ((hcf_lease->'expiresAt')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_lease->'expiresAt')::text END
      WHEN 'number' THEN CASE WHEN (hcf_lease->'expiresAt')::numeric=trunc((hcf_lease->'expiresAt')::numeric)
        AND (hcf_lease->'expiresAt')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_lease->'expiresAt')::numeric)::text END
      WHEN 'boolean' THEN (hcf_lease->'expiresAt')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"generation":'||(CASE jsonb_typeof((hcf_lease->'generation'))
      WHEN 'string' THEN CASE WHEN ((hcf_lease->'generation')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_lease->'generation')::text END
      WHEN 'number' THEN CASE WHEN (hcf_lease->'generation')::numeric=trunc((hcf_lease->'generation')::numeric)
        AND (hcf_lease->'generation')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_lease->'generation')::numeric)::text END
      WHEN 'boolean' THEN (hcf_lease->'generation')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"leaseId":'||(CASE jsonb_typeof((hcf_lease->'leaseId'))
      WHEN 'string' THEN CASE WHEN ((hcf_lease->'leaseId')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_lease->'leaseId')::text END
      WHEN 'number' THEN CASE WHEN (hcf_lease->'leaseId')::numeric=trunc((hcf_lease->'leaseId')::numeric)
        AND (hcf_lease->'leaseId')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_lease->'leaseId')::numeric)::text END
      WHEN 'boolean' THEN (hcf_lease->'leaseId')::text WHEN 'null' THEN 'null' ELSE NULL END)
  ]::text[];
        IF array_position(hcf_lease_parts,NULL::text) IS NULL THEN
          hcf_lease_text:='{'||array_to_string(hcf_lease_parts,',')||'}';
        END IF;
      END IF;
    END IF;
    hcf_parts:=ARRAY[
    '"attempt":'||(CASE jsonb_typeof((hcf_value->'attempt'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'attempt')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'attempt')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'attempt')::numeric=trunc((hcf_value->'attempt')::numeric)
        AND (hcf_value->'attempt')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'attempt')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'attempt')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"attemptLimit":'||(CASE jsonb_typeof((hcf_value->'attemptLimit'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'attemptLimit')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'attemptLimit')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'attemptLimit')::numeric=trunc((hcf_value->'attemptLimit')::numeric)
        AND (hcf_value->'attemptLimit')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'attemptLimit')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'attemptLimit')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"context":'||COALESCE((CASE jsonb_typeof((hcf_value->'context'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'context')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'context')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'context')::numeric=trunc((hcf_value->'context')::numeric)
        AND (hcf_value->'context')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'context')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'context')::text WHEN 'null' THEN 'null' ELSE NULL END),subtree_memo->>(((hcf_depth)+1)::text||':'||(hcf_value->'context')::text)),
    '"contextKey":'||(CASE jsonb_typeof((hcf_value->'contextKey'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'contextKey')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'contextKey')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'contextKey')::numeric=trunc((hcf_value->'contextKey')::numeric)
        AND (hcf_value->'contextKey')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'contextKey')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'contextKey')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"createdAt":'||(CASE jsonb_typeof((hcf_value->'createdAt'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'createdAt')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'createdAt')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'createdAt')::numeric=trunc((hcf_value->'createdAt')::numeric)
        AND (hcf_value->'createdAt')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'createdAt')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'createdAt')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"jobId":'||(CASE jsonb_typeof((hcf_value->'jobId'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'jobId')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'jobId')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'jobId')::numeric=trunc((hcf_value->'jobId')::numeric)
        AND (hcf_value->'jobId')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'jobId')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'jobId')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"jobKey":'||(CASE jsonb_typeof((hcf_value->'jobKey'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'jobKey')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'jobKey')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'jobKey')::numeric=trunc((hcf_value->'jobKey')::numeric)
        AND (hcf_value->'jobKey')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'jobKey')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'jobKey')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"kind":'||(CASE jsonb_typeof((hcf_value->'kind'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'kind')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'kind')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'kind')::numeric=trunc((hcf_value->'kind')::numeric)
        AND (hcf_value->'kind')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'kind')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'kind')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"lastFailure":'||(CASE jsonb_typeof((hcf_value->'lastFailure'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'lastFailure')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'lastFailure')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'lastFailure')::numeric=trunc((hcf_value->'lastFailure')::numeric)
        AND (hcf_value->'lastFailure')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'lastFailure')::numeric)::text END
      WHEN 'boolean' THEN (hcf_value->'lastFailure')::text WHEN 'null' THEN 'null' ELSE NULL END),
    '"lease":'||hcf_lease_text,
    '"method":'||COALESCE((CASE jsonb_typeof((hcf_value->'method'))
      WHEN 'string' THEN CASE WHEN ((hcf_value->'method')#>>'{}') ~ '[^ -~]' THEN NULL ELSE (hcf_value->'method')::text END
      WHEN 'number' THEN CASE WHEN (hcf_value->'method')::numeric=trunc((hcf_value->'method')::numeric)
        AND (hcf_value->'method')::numeric BETWEEN -9007199254740991 AND 9007199254740991 THEN trunc((hcf_value->'method')::numeric)::text END
