IF attempt_canonical IS NULL THEN
DECLARE hc0_value jsonb:=jsonb_build_object('subject',s.subject_text::jsonb,'claim',x.claim_text::jsonb,'leasedJob',x.leased_job,'authority',x.authority); hc0_depth integer:=0;
